  ('q_verbal_059', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'reading_comprehension', 'מה ניתן להסיק מהקטע על מקום האדם בעולם?', 'מדענים מעריכים כי הקוסמוס מכיל יותר מ-2 טריליון גלקסיות, כל אחת עם מאות מיליארדי כוכבים. השמש שלנו היא כוכב ממוצע בגלקסייה הכלה כ-400 מיליארד כוכבים אחרים. כדור הארץ מקיף את השמש מאז כ-4.5 מיליארד שנה, והחיים עליו החלו לפני כ-3.5 מיליארד שנה. בסולם הקוסמי, האדם הוא תופעה צעירה ביקום עצום.', '[{"id":"a","text":"האדם הוא מרכז היקום","isCorrect":false},{"id":"b","text":"האדם קיים זמן קצר ביחס ליקום","isCorrect":true},{"id":"c","text":"הגלקסיות כוכבים בודדים","isCorrect":false},{"id":"d","text":"כדור הארץ הוא כוכב ממוצע","isCorrect":false}]'::jsonb, 'b', 'הקטע מדגיש שהאדם הוא "תופעה צעירה ביקום עצום" — קיים זמן קצר ביחס לגיל היקום.', 4, '{"elo":1250,"discrimination":0.8033597305546882,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_060', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'מה המשמעות של המילה "פרגמטי"?', NULL, '[{"id":"a","text":"עיוני ופילוסופי","isCorrect":false},{"id":"b","text":"מעשי ומתמקד בתוצאות","isCorrect":true},{"id":"c","text":"נחרץ וחד משמעי","isCorrect":false},{"id":"d","text":"עדין ורגיש","isCorrect":false}]'::jsonb, 'b', '"פרגמטי" (מן המושג פרגמטיזם) = מעשי, ממוקד בתוצאות ולא בעקרונות תאורטיים.', 6, '{"elo":1380,"discrimination":0.7933677810137859,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
