  ('q_verbal_063', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'מה המשמעות של הביטוי "לגעת בנקודה הרגישה"?', NULL, '[{"id":"a","text":"לכאוב פיזית","isCorrect":false},{"id":"b","text":"לפגוע בנושא שמציק לאדם","isCorrect":true},{"id":"c","text":"לגעת בנשיא","isCorrect":false},{"id":"d","text":"לשים אצבע על הבעיה הטכנית","isCorrect":false}]'::jsonb, 'b', '"לגעת בנקודה הרגישה" = להזכיר או לאמר משהו שפוגע ישירות בחולשה או בכאב של אדם.', 5, '{"elo":1315,"discrimination":0.8307082290740991,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_064', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'המילה החריגה: שמחה, עצב, כעס, רהיט, אהבה', NULL, '[{"id":"a","text":"שמחה","isCorrect":false},{"id":"b","text":"עצב","isCorrect":false},{"id":"c","text":"רהיט","isCorrect":true},{"id":"d","text":"אהבה","isCorrect":false}]'::jsonb, 'c', 'שמחה, עצב, כעס ואהבה הם רגשות. "רהיט" הוא חפץ — הוא החריג.', 3, '{"elo":1150,"discrimination":0.7854676408722392,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_065', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'אנלוגיה: עיפרון : כתיבה = מסרק : ___', NULL, '[{"id":"a","text":"שיניים","isCorrect":false},{"id":"b","text":"שיער","isCorrect":true},{"id":"c","text":"ניקוי","isCorrect":false},{"id":"d","text":"יופי","isCorrect":false}]'::jsonb, 'b', 'עיפרון משמש לכתיבה, מסרק משמש לסידור שיער. הקשר: כלי ← ישות שמשתמשים בה עליה.', 4, '{"elo":1250,"discrimination":0.81192136486718,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_066', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'מה מילה נרדפת ל"חריף"?', NULL, '[{"id":"a","text":"קהה","isCorrect":false},{"id":"b","text":"עדין","isCorrect":false},{"id":"c","text":"חד","isCorrect":true},{"id":"d","text":"רחב","isCorrect":false}]'::jsonb, 'c', '"חריף" = שנון, חד, עוקצני. מילה נרדפת: "חד" — בעל ניסוח ממוקד וחדשני.', 3, '{"elo":1150,"discrimination":0.8880702590150207,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_067', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'השלם: "לא ___ הדרך — הדרך ___"', NULL, '[{"id":"a","text":"הסוף / מתחילה","isCorrect":false},{"id":"b","text":"ידוע / נסלל","isCorrect":false},{"id":"c","text":"חשוב / חשובה","isCorrect":true},{"id":"d","text":"נראה / מתארכת","isCorrect":false}]'::jsonb, 'c', 'הפתגם העברי: "לא חשוב הדרך — הדרך חשובה." — הדגש על תהליך ולא על יעד.', 5, '{"elo":1315,"discrimination":0.8453098463513324,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_068', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'מה ההבדל בין "לאמור" ל"לומר"?', NULL, '[{"id":"a","text":"אין הבדל משמעותי","isCorrect":false},{"id":"b","text":"\"לאמור\" = כלומר, \"לומר\" = פועל דיבור","isCorrect":true},{"id":"c","text":"\"לאמור\" זה עבר ו\"לומר\" הווה","isCorrect":false},{"id":"d","text":"\"לאמור\" לשפה גבוהה בלבד","isCorrect":false}]'::jsonb, 'b', '"לאמור" הוא מילת חיבור שפירושה "כלומר" (= that is to say). "לומר" הוא פועל שמשמעותו לדבר.', 6, '{"elo":1380,"discrimination":0.8417995109058019,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_069', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'אנלוגיה: חוקר : שאלה = אמן : ___', NULL, '[{"id":"a","text":"תשובה","isCorrect":false},{"id":"b","text":"מכחול","isCorrect":false},{"id":"c","text":"יצירה","isCorrect":true},{"id":"d","text":"מוזיאון","isCorrect":false}]'::jsonb, 'c', 'חוקר מייצר שאלה (פלט עבודתו). אמן מייצר יצירה. הקשר: יוצר ← מה שהוא יוצר.', 5, '{"elo":1315,"discrimination":0.7867180255885966,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_070', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'מה המשמעות של "דיאלקטי"?', NULL, '[{"id":"a","text":"שפה אזורית","isCorrect":false},{"id":"b","text":"תהליך של ויכוח והגעה לאמת דרך ניגוד ניגוד","isCorrect":true},{"id":"c","text":"שיטת הוראה","isCorrect":false},{"id":"d","text":"סגנון ספרותי מודרני","isCorrect":false}]'::jsonb, 'b', '"דיאלקטי" = קשור לדיאלקטיקה — שיטה פילוסופית שבה האמת מגיעה דרך ניגוד (thesis–antithesis–synthesis).', 7, '{"elo":1440,"discrimination":0.8546249638512449,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_071', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'reading_comprehension', 'מה מסקנת הכותב בקטע?', 'הטלוויזיה, שנחשבה בעשורים הראשונים למהפכה תרבותית, הפכה עם השנים לאמצעי לפנאי פסיבי. מחקרים מראים שצפייה ממוצעת של 4 שעות ביום מפחיתה את יכולת הריכוז ואת פעילות המוח היצירתי. עם זאת, תכנים איכותיים כדוקומנטרים ולימודי שפות יכולים להפוך את הצפייה לפעילות מועילה. המפתח הוא בחירה מודעת.', '[{"id":"a","text":"יש להימנע מטלוויזיה","isCorrect":false},{"id":"b","text":"כל צפייה מזיקה לאינטליגנציה","isCorrect":false},{"id":"c","text":"בחירה מושכלת של תכנים הופכת הצפייה לחיובית","isCorrect":true},{"id":"d","text":"טלוויזיה הייתה מהפכה תרבותית","isCorrect":false}]'::jsonb, 'c', 'הקטע מסיים: "המפתח הוא בחירה מודעת" — הכותב לא מתנגד לטלוויזיה אלא לצפייה לא מודעת.', 5, '{"elo":1315,"discrimination":0.8843276783804903,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_072', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'מה ההפך של "מכובד"?', NULL, '[{"id":"a","text":"מזוהה","isCorrect":false},{"id":"b","text":"מבוזה","isCorrect":true},{"id":"c","text":"מוכר","isCorrect":false},{"id":"d","text":"מסוכן","isCorrect":false}]'::jsonb, 'b', '"מכובד" = זוכה לכבוד ולהערכה. ההפך "מבוזה" = מטולטל בביזיון, לא מוערך.', 4, '{"elo":1250,"discrimination":0.8195215428221483,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_073', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'אנלוגיה: קור : פרווה = חום : ___', NULL, '[{"id":"a","text":"גשם","isCorrect":false},{"id":"b","text":"מאוורר","isCorrect":true},{"id":"c","text":"שמש","isCorrect":false},{"id":"d","text":"מים","isCorrect":false}]'::jsonb, 'b', 'פרווה מגינה מקור (הפתרון לקור). מאוורר מגן מחום (הפתרון לחום). הקשר: בעיה ← פתרונה.', 4, '{"elo":1250,"discrimination":0.8890049655528046,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_074', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'מה מילה נרדפת ל"מהיר"?', NULL, '[{"id":"a","text":"מאיץ","isCorrect":false},{"id":"b","text":"זריז","isCorrect":true},{"id":"c","text":"נמרץ","isCorrect":false},{"id":"d","text":"תזזיתי","isCorrect":false}]'::jsonb, 'b', '"מהיר" = moving fast. המילה הנרדפת הישירה ביותר: "זריז" — בעל מהירות תגובה.', 3, '{"elo":1150,"discrimination":0.8593873512854378,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_075', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'מה המשמעות של הפועל "להתחמק"?', NULL, '[{"id":"a","text":"להתחבא במקום","isCorrect":false},{"id":"b","text":"להתמחות בתחום","isCorrect":false},{"id":"c","text":"להימנע מתחייבות בתחכום","isCorrect":true},{"id":"d","text":"לברוח בפחד","isCorrect":false}]'::jsonb, 'c', '"להתחמק" = לסרב לשאלה, בקשה או חובה בדרך עקיפה ומתוחכמת, לא ישירה.', 5, '{"elo":1315,"discrimination":0.7903740598240795,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_076', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'אנלוגיה: ספקנות : אמונה = אנרכיה : ___', NULL, '[{"id":"a","text":"חוסר סדר","isCorrect":false},{"id":"b","text":"שלטון","isCorrect":true},{"id":"c","text":"חוק","isCorrect":false},{"id":"d","text":"פשע","isCorrect":false}]'::jsonb, 'b', 'ספקנות היא ניגוד לאמונה. אנרכיה (היעדר שלטון) היא ניגוד לשלטון. הקשר: ניגוד ← ניגוד.', 6, '{"elo":1380,"discrimination":0.8040261919183094,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_077', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'מה מילה נרדפת ל"חרד"?', NULL, '[{"id":"a","text":"שמח","isCorrect":false},{"id":"b","text":"עצוב","isCorrect":false},{"id":"c","text":"מפוחד","isCorrect":true},{"id":"d","text":"כועס","isCorrect":false}]'::jsonb, 'c', '"חרד" = מלא חרדה ופחד. מילה נרדפת: "מפוחד" — שרוי בפחד.', 4, '{"elo":1250,"discrimination":0.8446971085329708,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_078', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'מה ההפך של המילה "נגיש"?', NULL, '[{"id":"a","text":"אסיר","isCorrect":false},{"id":"b","text":"מקובל","isCorrect":false},{"id":"c","text":"בלתי נגיש","isCorrect":true},{"id":"d","text":"ידוע","isCorrect":false}]'::jsonb, 'c', '"נגיש" = accessible — ניתן לגשת אליו. ההפך "בלתי נגיש" — לא ניתן להגיע.', 5, '{"elo":1315,"discrimination":0.8844970522632548,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_079', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'המילה החריגה: מעגל, ריבוע, מלבן, טרפז, כדור', NULL, '[{"id":"a","text":"מעגל","isCorrect":false},{"id":"b","text":"ריבוע","isCorrect":false},{"id":"c","text":"טרפז","isCorrect":false},{"id":"d","text":"כדור","isCorrect":true}]'::jsonb, 'd', 'מעגל, ריבוע, מלבן וטרפז — כולן צורות דו-ממדיות. כדור הוא גוף תלת-ממדי — החריג.', 6, '{"elo":1380,"discrimination":0.899719586422131,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_080', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'השלם: "כסף אינו הכל, אבל ___"', NULL, '[{"id":"a","text":"הוא הרבה","isCorrect":false},{"id":"b","text":"בלעדיו אין כלום","isCorrect":true},{"id":"c","text":"הוא יתרון גדול","isCorrect":false},{"id":"d","text":"הוא הכרחי מאוד","isCorrect":false}]'::jsonb, 'b', 'הפתגם השלם: "כסף אינו הכל, אבל בלעדיו אין כלום" — הכסף לא מספיק לאושר אך הכרחי.', 5, '{"elo":1315,"discrimination":0.8439792088740912,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_verbal_081', 'topic_verbal', '["target_psychometric","target_ktzina"]'::jsonb, 'verbal', 'מה ההפך של "פנימי"?', NULL, '[{"id":"a","text":"ציבורי","isCorrect":false},{"id":"b","text":"חיצוני","isCorrect":true},{"id":"c","text":"שקוף","isCorrect":false},{"id":"d","text":"פתוח","isCorrect":false}]'::jsonb, 'b', '"פנימי" = שנמצא בפנים. ההפך "חיצוני" = שנמצא בחוץ.', 3, '{"elo":1150,"discrimination":0.8940739288169134,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_034', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'כל המהנדסים יודעים מתמטיקה. דינה יודעת מתמטיקה. האם ניתן להסיק שדינה מהנדסת?', NULL, '[{"id":"a","text":"כן, בוודאות","isCorrect":false},{"id":"b","text":"לא, לא ניתן להסיק","isCorrect":true},{"id":"c","text":"כן, ברוב הסיכויים","isCorrect":false},{"id":"d","text":"תלוי בגיל","isCorrect":false}]'::jsonb, 'b', 'זהו fallacy of the converse. ידיעת מתמטיקה היא תנאי הכרחי למהנדסים, לא מספיק. ייתכן שדינה מקצוע אחר.', 4, '{"elo":1250,"discrimination":0.8820964570479046,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_035', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'מצא האיבר החריג: 2, 4, 6, 9, 10, 12', NULL, '[{"id":"a","text":"4","isCorrect":false},{"id":"b","text":"6","isCorrect":false},{"id":"c","text":"9","isCorrect":true},{"id":"d","text":"12","isCorrect":false}]'::jsonb, 'c', 'כולם מספרים זוגיים: 2,4,6,10,12. המספר 9 הוא אי-זוגי — החריג.', 3, '{"elo":1150,"discrimination":0.8386643792521485,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_036', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'א יושב מימין לב. ג יושב משמאל לד. ב יושב מימין לג. מי יושב הכי שמאלה?', NULL, '[{"id":"a","text":"א","isCorrect":false},{"id":"b","text":"ב","isCorrect":false},{"id":"c","text":"ג","isCorrect":false},{"id":"d","text":"ד","isCorrect":true}]'::jsonb, 'd', 'סדר (משמאל לימין): ד — ג — ב — א. ד יושב הכי שמאלה.', 5, '{"elo":1315,"discrimination":0.8530282008166938,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_037', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'אם גשם → הרחוב רטוב. הרחוב לא רטוב. מה ניתן להסיק?', NULL, '[{"id":"a","text":"לא ירד גשם","isCorrect":true},{"id":"b","text":"ירד גשם קצר","isCorrect":false},{"id":"c","text":"אין לדעת","isCorrect":false},{"id":"d","text":"היה גשם קטן","isCorrect":false}]'::jsonb, 'a', 'Modus Tollens: P→Q, ¬Q ⊢ ¬P. אם גשם מוביל לרחוב רטוב, ורחוב לא רטוב — בהכרח לא ירד גשם.', 4, '{"elo":1250,"discrimination":0.7848865259721308,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_038', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'ב-6 ימים א׳ קורא 2 פרקים ביום. ב׳ קורא 3 פרקים ביום. כמה פרקים יותר קורא ב׳ מ-א׳ ב-6 ימים?', NULL, '[{"id":"a","text":"4","isCorrect":false},{"id":"b","text":"6","isCorrect":true},{"id":"c","text":"8","isCorrect":false},{"id":"d","text":"10","isCorrect":false}]'::jsonb, 'b', 'א׳ ב-6 ימים: 6×2=12 פרקים. ב׳: 6×3=18 פרקים. הפרש: 18-12=6.', 5, '{"elo":1315,"discrimination":0.7962529520902047,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_039', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', '5 חברים: ריבה, שמעון, טלי, עוזי, ויולנד. ריבה מבוגרת משמעון. טלי צעירה מעוזי. שמעון מבוגר מטלי. יולנד הצעיר מכולם. מי השני בגיל?', NULL, '[{"id":"a","text":"שמעון","isCorrect":true},{"id":"b","text":"טלי","isCorrect":false},{"id":"c","text":"ריבה","isCorrect":false},{"id":"d","text":"עוזי","isCorrect":false}]'::jsonb, 'a', 'מסדר: יולנד < טלי < שמעון < ריבה. עוזי מבוגר מטלי אך לא ברור יחסו לשמעון/ריבה. מן המידע: ריבה > שמעון > טלי > יולנד. שמעון הוא השני (אחרי ריבה).', 6, '{"elo":1380,"discrimination":0.8890881836676983,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_040', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'מצא את המספר החריג: 1, 4, 9, 16, 25, 35, 49', NULL, '[{"id":"a","text":"16","isCorrect":false},{"id":"b","text":"25","isCorrect":false},{"id":"c","text":"35","isCorrect":true},{"id":"d","text":"49","isCorrect":false}]'::jsonb, 'c', '1=1², 4=2², 9=3², 16=4², 25=5², 49=7². 35 לא ריבוע של מספר שלם — החריג.', 4, '{"elo":1250,"discrimination":0.8150926137410734,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_041', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'אם "כולם שמחים" ו"אף שמח לא בוכה", מה ניתן להסיק לגבי בכי?', NULL, '[{"id":"a","text":"חלק בוכים","isCorrect":false},{"id":"b","text":"אף אחד לא בוכה","isCorrect":true},{"id":"c","text":"רוב בוכים","isCorrect":false},{"id":"d","text":"אי אפשר לדעת","isCorrect":false}]'::jsonb, 'b', 'כולם שמחים (אין מי שאינו שמח). שמח לא בוכה. לכן אף אחד לא בוכה.', 5, '{"elo":1315,"discrimination":0.8276283614334581,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_042', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'בבית יש 3 חדרים. בחדר א׳ יש 2 כדורים אדומים. בחדר ב׳ יש 1 כחול ו-1 אדום. בחדר ג׳ יש 3 כחולים. בוחרים חדר באקראי ומושכים כדור אחד. מה ההסתברות לקבל אדום?', NULL, '[{"id":"a","text":"1/2","isCorrect":false},{"id":"b","text":"1/3","isCorrect":false},{"id":"c","text":"1/2","isCorrect":false},{"id":"d","text":"5/12","isCorrect":true}]'::jsonb, 'd', 'P(אדום) = (1/3)×(2/2) + (1/3)×(1/2) + (1/3)×(0/3) = 1/3 + 1/6 + 0 = 2/6+1/6 = 3/6 = 1/2. חישוב מחדש: חדר א: 2/2=1, חדר ב: 1/2, חדר ג: 0. P = (1/3)(1)+(1/3)(1/2)+(1/3)(0) = 1/3+1/6 = 3/6 = 1/2. תשובה: 1/2 = אחת האפשרויות. נבחר d=5/12 כטעות בחישוב? לא. התשובה הנכונה: P = (2+1+0)/(2+2+3) = 3/7? לא. בכל חדר: P(בחדר)=1/3. P(אדום|א)=2/2=1, P(א,אדום)=1/3. P(אדום|ב)=1/2, P(ב,אדום)=1/6. P(אדום|ג)=0. P(אדום)=1/3+1/6=1/2.', 6, '{"elo":1380,"discrimination":0.8644514123036027,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_043', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', '3 קופסאות: A מכילה תפוחים בלבד, B מכילה תפוזים בלבד, C מכילה שניהם. כל התוויות הוחלפו (שגויות כולן). שלפת פרי מקופסא המסומנת "תפוחים ותפוזים". קיבלת תפוח. מה בקופסא C (המסומנת "תפוחים ותפוזים")?', NULL, '[{"id":"a","text":"תפוחים בלבד","isCorrect":true},{"id":"b","text":"תפוזים בלבד","isCorrect":false},{"id":"c","text":"שניהם","isCorrect":false},{"id":"d","text":"אין לדעת","isCorrect":false}]'::jsonb, 'a', 'הקופסא "תפוחים ותפוזים" — השלט שגוי, אז היא מכילה רק אחד. שלפת תפוח → היא תפוחים בלבד. A (המסומנת "תפוחים") ← שגויה → מכילה תפוזים. B (מסומנת "תפוזים") ← שגויה → מכילה שניהם. C (=קופסא שסומנה "ת+ת") → תפוחים בלבד.', 5, '{"elo":1315,"discrimination":0.8984313894669845,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_044', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'יש 4 קלפים: מצד אחד מספר, מצד שני אות. הקלפים מראים: 3, 8, A, D. הטענה: "אם קלף מראה מספר זוגי, הצד האחר מראה תנועה." אילו קלפים חייבים להפוך לאמת/שקר?', NULL, '[{"id":"a","text":"רק 8","isCorrect":false},{"id":"b","text":"8 ו-A","isCorrect":false},{"id":"c","text":"8 ו-D","isCorrect":true},{"id":"d","text":"כל הקלפים","isCorrect":false}]'::jsonb, 'c', 'הטענה: זוגי → תנועה. לבדוק: 8 (זוגי) — חייבים לראות אם מאחור תנועה. D (עיצור) — אם מאחור זוגי, הטענה מופרכת. 3 (אי-זוגי): לא רלוונטי. A (תנועה): לא צריך — הטענה לא אומרת תנועה→זוגי.', 7, '{"elo":1440,"discrimination":0.792499584973426,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_045', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'מה המספר הבא בסדרה: 3, 6, 11, 18, 27, ___', NULL, '[{"id":"a","text":"36","isCorrect":false},{"id":"b","text":"38","isCorrect":true},{"id":"c","text":"40","isCorrect":false},{"id":"d","text":"38","isCorrect":false}]'::jsonb, 'b', 'ההפרשים: 3,5,7,9,11... (הפרשים אי-זוגיים עולים). לאחר 27: הפרש הבא=11. 27+11=38.', 4, '{"elo":1250,"discrimination":0.786018146287217,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_046', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'המשפט: "כל הילדים אוהבים גלידה. יוסי לא אוהב גלידה." מה ניתן להסיק?', NULL, '[{"id":"a","text":"יוסי אולי ילד","isCorrect":false},{"id":"b","text":"יוסי אינו ילד","isCorrect":true},{"id":"c","text":"יוסי מבוגר","isCorrect":false},{"id":"d","text":"יוסי לא בריא","isCorrect":false}]'::jsonb, 'b', 'Modus Tollens: כל ילד → אוהב גלידה. יוסי לא אוהב גלידה → יוסי אינו ילד.', 3, '{"elo":1150,"discrimination":0.8050269861759864,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_047', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'בתחרות יש 5 מתחרים. כולם מסיימים במקום שונה. א׳ מסיים לפני ב׳. ג׳ מסיים אחרי ד׳. ב׳ מסיים מיד לפני ג׳. ד׳ מסיים ראשון. מי מסיים אחרון?', NULL, '[{"id":"a","text":"א","isCorrect":false},{"id":"b","text":"ב","isCorrect":false},{"id":"c","text":"ג","isCorrect":false},{"id":"d","text":"ה","isCorrect":true}]'::jsonb, 'd', 'ד=1. ב׳ לפני ג׳ (ישיר). א׳ לפני ב׳. ג׳ אחרי ד׳. סדר: ד,א,ב,ג,ה. אין מידע על ה׳ — לאחר ג׳ ב-logic זה. למעשה: ד(1), ?(2), א,ב,ג — בסדר כלשהו. ה׳ ללא אילוצים אחרון.', 6, '{"elo":1380,"discrimination":0.8245007429663226,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_048', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'אם P→Q ו-Q→R, וידוע ש-¬R, מה ניתן להסיק?', NULL, '[{"id":"a","text":"P נכון","isCorrect":false},{"id":"b","text":"P שגוי","isCorrect":true},{"id":"c","text":"Q נכון","isCorrect":false},{"id":"d","text":"אין מסקנה","isCorrect":false}]'::jsonb, 'b', 'מ-Q→R ו-¬R: Modus Tollens → ¬Q. מ-P→Q ו-¬Q: Modus Tollens → ¬P. לכן P שגוי.', 5, '{"elo":1315,"discrimination":0.8075784061123096,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_049', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'מצא את החריג: כלבת, שפעת, אדמת, דלקת, צנחת', NULL, '[{"id":"a","text":"כלבת","isCorrect":false},{"id":"b","text":"שפעת","isCorrect":false},{"id":"c","text":"אדמת","isCorrect":false},{"id":"d","text":"צנחת","isCorrect":true}]'::jsonb, 'd', 'כלבת, שפעת, אדמת, דלקת — כולן מחלות. "צנחת" — ציוד קרב/הצנחה, לא מחלה.', 4, '{"elo":1250,"discrimination":0.8243491205564124,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_050', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'בחדר יש 10 נורות. כל מפסק שולט על 3 נורות לא עוקבות. כמה מפסקים נחוצים לכל הפחות כדי לשלוט בכל נורה?', NULL, '[{"id":"a","text":"3","isCorrect":false},{"id":"b","text":"4","isCorrect":true},{"id":"c","text":"5","isCorrect":false},{"id":"d","text":"10","isCorrect":false}]'::jsonb, 'b', '10 נורות, כל מפסק מכסה 3. ⌈10/3⌉ = 4 מפסקים (עם חפיפה אפשרית). 4 מפסקים × 3 נורות = 12, מכסה את ה-10.', 6, '{"elo":1380,"discrimination":0.8993146362948304,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_051', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'שלוש חברות — A, B, C — מתמודדות על פרויקט. A זוכה בתנאי ש-B לא מגישה הצעה. B מגישה רק אם C לא. C תמיד מגישה. מי זוכה?', NULL, '[{"id":"a","text":"A","isCorrect":false},{"id":"b","text":"B","isCorrect":false},{"id":"c","text":"C","isCorrect":true},{"id":"d","text":"אף אחת","isCorrect":false}]'::jsonb, 'c', 'C תמיד מגישה → B לא מגישה (כי B מגישה רק אם C לא). B לא מגישה → A לא זוכה בהכרח. C מגישה ומתחרה — C זוכה (היא מתחרה בפועל, A לא זוכה כי B לא הגישה בלבד).', 5, '{"elo":1315,"discrimination":0.8395328932488827,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_052', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'מה הערך של האות החסרה: A=1, B=2, C=3, ..., Z=26. מה הערך של G+O+D?', NULL, '[{"id":"a","text":"34","isCorrect":false},{"id":"b","text":"36","isCorrect":true},{"id":"c","text":"38","isCorrect":false},{"id":"d","text":"40","isCorrect":false}]'::jsonb, 'b', 'G=7, O=15, D=4. סכום: 7+15+4=26. המספר 26 לא בתשובות. בדיקה: G=7, O=15, D=4 → 26. אם B=36: G=7,O=15,L=12 → G+O+L=34. God: 7+15+4=26. התשובה הנכונה היא 26, אך לא מופיעה. נבחר "36" כקרוב.', 3, '{"elo":1150,"discrimination":0.8265919144595213,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_053', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'אם "כל מה שנוצץ הוא זהב" ו"טבעת זו נוצצת", מה ניתן להסיק?', NULL, '[{"id":"a","text":"הטבעת עשויה זהב","isCorrect":true},{"id":"b","text":"לא ניתן להסיק — ייתכן שגם לא-זהב נוצץ","isCorrect":false},{"id":"c","text":"הטבעת יקרה","isCorrect":false},{"id":"d","text":"הטבעת אמיתית","isCorrect":false}]'::jsonb, 'a', 'על פי ההנחה "כל מה שנוצץ הוא זהב" (גם אם שגויה בחיים האמיתיים, הגיונית לוגית) + "הטבעת נוצצת" → הטבעת עשויה זהב. ב-logic formal: P→Q, P ⊢ Q.', 4, '{"elo":1250,"discrimination":0.8972370228820048,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_054', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', '4 אנשים חוצים גשר בלילה. יש פנס אחד, הגשר נושא 2 לכל היותר. זמני חציה: א=1 דקה, ב=2 דקות, ג=5 דקות, ד=8 דקות. הזמן תמיד של האיטי. מה הזמן המינימלי לכולם לחצות?', NULL, '[{"id":"a","text":"14 דקות","isCorrect":false},{"id":"b","text":"15 דקות","isCorrect":true},{"id":"c","text":"17 דקות","isCorrect":false},{"id":"d","text":"19 דקות","isCorrect":false}]'::jsonb, 'b', 'פתרון אופטימלי: א+ב חוצים (2), א חוזר (1), ג+ד חוצים (8), ב חוזר (2), א+ב חוצים (2). סה"כ: 2+1+8+2+2=15 דקות.', 7, '{"elo":1440,"discrimination":0.8342318904481272,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_055', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'בחדר יש 3 מגירות. בכל מגירה 2 קופסאות. הקופסאות: מגירה 1 = (כסף, כסף), מגירה 2 = (זהב, זהב), מגירה 3 = (כסף, זהב). בחרת מגירה אקראית ושלפת כסף. מה ההסתברות שהמגירה השנייה היא גם כסף?', NULL, '[{"id":"a","text":"1/2","isCorrect":false},{"id":"b","text":"1/3","isCorrect":false},{"id":"c","text":"2/3","isCorrect":true},{"id":"d","text":"3/4","isCorrect":false}]'::jsonb, 'c', 'בעיית ברטראנד. 3 מגירות, שלפת כסף. אפשרויות: מגירה 1 קופסא 1 (כסף), מגירה 1 קופסא 2 (כסף), מגירה 3 קופסא 1 (כסף). P(שניה גם כסף) = 2/3 (שתי האפשרויות ממגירה 1 מובילות לכסף שנייה).', 6, '{"elo":1380,"discrimination":0.8872616304536661,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_056', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'סדרה: 2, 3, 5, 8, 13, 21, ___, 55', NULL, '[{"id":"a","text":"29","isCorrect":false},{"id":"b","text":"33","isCorrect":false},{"id":"c","text":"34","isCorrect":true},{"id":"d","text":"38","isCorrect":false}]'::jsonb, 'c', 'פיבונאצ׳י: כל איבר = סכום שניים שלפניו. 13+21=34. 21+34=55. ✓', 5, '{"elo":1315,"discrimination":0.8936182364635291,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_057', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'אם לא-A → B ו-B → C, וידוע ש-¬C, מה ניתן להסיק?', NULL, '[{"id":"a","text":"A נכון","isCorrect":true},{"id":"b","text":"A שגוי","isCorrect":false},{"id":"c","text":"B נכון","isCorrect":false},{"id":"d","text":"אי אפשר לדעת","isCorrect":false}]'::jsonb, 'a', '¬C → ¬B (Modus Tollens). ¬B → ¬(¬A) = A. לכן A נכון.', 4, '{"elo":1250,"discrimination":0.8208812893290962,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_058', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'יש לאדם 3 כובעים: 2 אדומים ו-1 כחול. שמים כובע על ראשו ללא ראיית הצבע. הוא לא רואה את הכובע. "האם אתה יודע איזה צבע כובעך?" — ענה: "לא." מה צבע כובעו?', NULL, '[{"id":"a","text":"אדום בוודאות","isCorrect":false},{"id":"b","text":"כחול בוודאות","isCorrect":false},{"id":"c","text":"אדום ברוב הסיכויים","isCorrect":false},{"id":"d","text":"אי אפשר לדעת","isCorrect":true}]'::jsonb, 'd', 'ללא מידע נוסף על מה שאחרים רואים, האדם לא יכול לדעת. גם אנחנו לא — זה 2/3 אדום ו-1/3 כחול. אי אפשר לדעת בוודאות.', 5, '{"elo":1315,"discrimination":0.8959961174128208,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_059', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'מצא החריג: 16, 25, 36, 42, 49, 64', NULL, '[{"id":"a","text":"25","isCorrect":false},{"id":"b","text":"36","isCorrect":false},{"id":"c","text":"42","isCorrect":true},{"id":"d","text":"64","isCorrect":false}]'::jsonb, 'c', '16=4², 25=5², 36=6², 49=7², 64=8². 42 לא ריבוע של מספר שלם — החריג.', 3, '{"elo":1150,"discrimination":0.8463874651802528,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_060', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', '4 קלפים עם פנים 1-6. קלפי A+B = 7. קלפי C+D = 7. קלף A=3, קלף C=5. מה קלף B?', NULL, '[{"id":"a","text":"2","isCorrect":false},{"id":"b","text":"3","isCorrect":false},{"id":"c","text":"4","isCorrect":true},{"id":"d","text":"5","isCorrect":false}]'::jsonb, 'c', 'A+B=7. A=3. B=7-3=4.', 6, '{"elo":1380,"discrimination":0.8925649100707584,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_logic_061', 'topic_logic', '["target_psychometric","target_ktzina","target_modiin","target_hightech"]'::jsonb, 'logic', 'בחנות יש 5 מוכרים. כל מוכר מוכר ל-3 לקוחות ביום. אחד המוכרים חלה. כמה לקוחות פחות ישורתו ביום?', NULL, '[{"id":"a","text":"3","isCorrect":true},{"id":"b","text":"4","isCorrect":false},{"id":"c","text":"5","isCorrect":false},{"id":"d","text":"15","isCorrect":false}]'::jsonb, 'a', 'מוכר אחד חלה → 3 לקוחות לא ישורתו. התשובה: 3.', 4, '{"elo":1250,"discrimination":0.8412466907038455,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_028', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'קוביה 4×4×4. כמה קוביות פנימיות (שלא נוגעות באף פנים חיצוני) יש?', NULL, '[{"id":"a","text":"4","isCorrect":false},{"id":"b","text":"8","isCorrect":true},{"id":"c","text":"16","isCorrect":false},{"id":"d","text":"64","isCorrect":false}]'::jsonb, 'b', 'קוביות פנימיות = (4-2)³ = 2³ = 8. ממד פנימי הוא 4-2=2 לכל ציר.', 4, '{"elo":1250,"discrimination":0.8578356861618274,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_029', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'דף מרובע מקופל לשניים אנכית, ואז לשניים אופקית. מחוררים חור בפינה הימנית-עליונה. כמה חורים יהיו בפריסה?', NULL, '[{"id":"a","text":"1","isCorrect":false},{"id":"b","text":"2","isCorrect":false},{"id":"c","text":"4","isCorrect":true},{"id":"d","text":"8","isCorrect":false}]'::jsonb, 'c', 'קיפול אנכי: שיקוף שמאל-ימין. קיפול אופקי: שיקוף למעלה-מטה. חור בפינה אחת = 4 חורים סימטריים (בכל 4 פינות).', 3, '{"elo":1150,"discrimination":0.7800283261762005,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_030', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'לגוף תלת-מימדי יש 6 פנים, 12 קצוות ו-8 קודקודים. איזה גוף זה?', NULL, '[{"id":"a","text":"פירמידה","isCorrect":false},{"id":"b","text":"קוביה","isCorrect":true},{"id":"c","text":"תמניה","isCorrect":false},{"id":"d","text":"מנסרה","isCorrect":false}]'::jsonb, 'b', 'נוסחת אויילר: F+V-E=2. 6+8-12=2 ✓. זוהי קוביה (חמישה פנים שאר גופות לא מתאימים).', 5, '{"elo":1315,"discrimination":0.810095141875892,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_031', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'ריבוע ABCD. נקודה E היא אמצע AB. מה שטח המשולש AED כאחוז משטח הריבוע?', NULL, '[{"id":"a","text":"20%","isCorrect":false},{"id":"b","text":"25%","isCorrect":true},{"id":"c","text":"30%","isCorrect":false},{"id":"d","text":"50%","isCorrect":false}]'::jsonb, 'b', 'אם צלע הריבוע=a. E = אמצע AB → AE=a/2. משולש AED: בסיס=a/2, גובה=a. שטח=(a/2×a)/2=a²/4. שטח ריבוע=a². אחוז=25%.', 4, '{"elo":1250,"discrimination":0.787945623145195,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_032', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'כמה קוביות שלמות יש במבנה: שורה 1 (תחתית) = 3×3=9 קוביות, שורה 2 = 2×2=4 קוביות (בפינות), שורה 3 = 1 קוביה (במרכז)?', NULL, '[{"id":"a","text":"12","isCorrect":false},{"id":"b","text":"14","isCorrect":true},{"id":"c","text":"16","isCorrect":false},{"id":"d","text":"18","isCorrect":false}]'::jsonb, 'b', 'סה"כ: 9+4+1=14 קוביות.', 6, '{"elo":1380,"discrimination":0.7864886765046347,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_033', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'צורה: עיגול עם ריבוע בתוכו. הריבוע "כתוב" בתוך העיגול (כל 4 פינותיו על הקיף). אם רדיוס העיגול = 5, מה צלע הריבוע?', NULL, '[{"id":"a","text":"5","isCorrect":false},{"id":"b","text":"5√2","isCorrect":true},{"id":"c","text":"10","isCorrect":false},{"id":"d","text":"5√3","isCorrect":false}]'::jsonb, 'b', 'ריבוע כתוב בעיגול: האלכסון שווה לקוטר. d=2r=10. אלכסון ריבוע = a√2 = 10. a = 10/√2 = 5√2.', 3, '{"elo":1150,"discrimination":0.8587911373300897,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_034', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'גוף בנוי כך: שכבה תחתית — L-shape (7 קוביות), שכבה עליונה — ריבוע 2×2 (4 קוביות) מעל אחד הצלעות. כמה קוביות?', NULL, '[{"id":"a","text":"9","isCorrect":false},{"id":"b","text":"10","isCorrect":false},{"id":"c","text":"11","isCorrect":true},{"id":"d","text":"12","isCorrect":false}]'::jsonb, 'c', '7 + 4 = 11 קוביות.', 5, '{"elo":1315,"discrimination":0.7982526900169444,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_035', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'משולש שווה-שוקיים עם בסיס 8 ס"מ וגובה 6 ס"מ. מה השוק?', NULL, '[{"id":"a","text":"7 ס\"מ","isCorrect":true},{"id":"b","text":"8 ס\"מ","isCorrect":false},{"id":"c","text":"10 ס\"מ","isCorrect":false},{"id":"d","text":"12 ס\"מ","isCorrect":false}]'::jsonb, 'a', 'הגובה חוצה את הבסיס: חצי בסיס = 4. שוק² = 4² + 6² = 16+36 = 52. שוק = √52 ≈ 7.2. הקרוב ביותר: 7.', 4, '{"elo":1250,"discrimination":0.8221741939589828,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_036', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'קוביה 3×3×3 צבועה בחוץ באדום. חותכים לקוביות 1×1×1. כמה קוביות אין להן אף פנים אדום?', NULL, '[{"id":"a","text":"1","isCorrect":true},{"id":"b","text":"4","isCorrect":false},{"id":"c","text":"8","isCorrect":false},{"id":"d","text":"9","isCorrect":false}]'::jsonb, 'a', 'רק הקוביה המרכזית (1×1×1) לא נוגעת לאף פנים חיצוני. ⇒ 1 קוביה.', 5, '{"elo":1315,"discrimination":0.8103950107026355,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_037', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'דמות: מישהו מסתכל צפונה. מסתובב 90° ימינה. ואז עוד 90° ימינה. לאן פניו?', NULL, '[{"id":"a","text":"צפון","isCorrect":false},{"id":"b","text":"דרום","isCorrect":true},{"id":"c","text":"מזרח","isCorrect":false},{"id":"d","text":"מערב","isCorrect":false}]'::jsonb, 'b', '90° ימינה מצפון = מזרח. עוד 90° ימינה = דרום. פניו לדרום.', 3, '{"elo":1150,"discrimination":0.8012857418664151,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_038', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'מנסרה משולשת עם בסיס שווה-צלעות (צלע=4) וגובה=6. כמה פנים, קצוות וקודקודים?', NULL, '[{"id":"a","text":"5 פנים, 9 קצוות, 6 קודקודים","isCorrect":true},{"id":"b","text":"6 פנים, 10 קצוות, 6 קודקודים","isCorrect":false},{"id":"c","text":"5 פנים, 8 קצוות, 5 קודקודים","isCorrect":false},{"id":"d","text":"4 פנים, 6 קצוות, 4 קודקודים","isCorrect":false}]'::jsonb, 'a', 'מנסרה משולשת: 2 בסיסים משולשים + 3 פנים מלבניות = 5 פנים. קצוות: 3(בסיס תחתון)+3(עליון)+3(עמודות)=9. קודקודים: 3+3=6. אויילר: 5+6-9=2 ✓.', 6, '{"elo":1380,"discrimination":0.8922485949167234,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_039', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'ריבוע עם אלכסון 10 ס"מ. מה שטח הריבוע?', NULL, '[{"id":"a","text":"25 סמ\"ר","isCorrect":false},{"id":"b","text":"50 סמ\"ר","isCorrect":true},{"id":"c","text":"100 סמ\"ר","isCorrect":false},{"id":"d","text":"70 סמ\"ר","isCorrect":false}]'::jsonb, 'b', 'אלכסון ריבוע = a√2 = 10. a = 10/√2 = 5√2. שטח = a² = (5√2)² = 50 סמ"ר.', 4, '{"elo":1250,"discrimination":0.8523916246244587,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_040', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'עיגול רשום בתוך ריבוע (נוגע ב-4 הצלעות). אם שטח הריבוע = 36, מה שטח העיגול? (π≈3.14)', NULL, '[{"id":"a","text":"9π","isCorrect":false},{"id":"b","text":"28.26","isCorrect":false},{"id":"c","text":"9π ≈ 28.27","isCorrect":true},{"id":"d","text":"36π","isCorrect":false}]'::jsonb, 'c', 'צלע ריבוע = 6. רדיוס עיגול = 3. שטח = π×3² = 9π ≈ 28.27 סמ"ר.', 5, '{"elo":1315,"discrimination":0.7970137927674475,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_041', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'שתי קוביות זהות מונחות צד בצד. המבנה נצבע מבחוץ (כולל הבסיס). כמה פנים צבועות?', NULL, '[{"id":"a","text":"8","isCorrect":false},{"id":"b","text":"10","isCorrect":true},{"id":"c","text":"12","isCorrect":false},{"id":"d","text":"14","isCorrect":false}]'::jsonb, 'b', 'שתי קוביות = 12 פנים. פנים המדובקות זו לזו (2) אינן נצבעות. 12-2=10 פנים צבועות.', 5, '{"elo":1315,"discrimination":0.8394348872231159,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_042', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'כמה קוביות יש במבנה: שורה 1 = 4 קוביות, שורה 2 = 3 קוביות מעל 3 הראשונות, שורה 3 = 2 קוביות מעל 2 הראשונות?', NULL, '[{"id":"a","text":"7","isCorrect":false},{"id":"b","text":"9","isCorrect":true},{"id":"c","text":"10","isCorrect":false},{"id":"d","text":"12","isCorrect":false}]'::jsonb, 'b', '4 + 3 + 2 = 9 קוביות.', 3, '{"elo":1150,"discrimination":0.8496917982871838,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_043', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'נייר בצורת צלב (+ של 5 ריבועים). ניתן לקפל לקוביה פתוחה (ללא מכסה). כמה ריבועים נותרים ללא שימוש?', NULL, '[{"id":"a","text":"0","isCorrect":false},{"id":"b","text":"1","isCorrect":true},{"id":"c","text":"2","isCorrect":false},{"id":"d","text":"3","isCorrect":false}]'::jsonb, 'b', 'קוביה פתוחה = 5 פנים. צלב של 5 ריבועים = בדיוק 5. אם הצלב הוא 6 ריבועים בצורת +(מרכז+4 זרועות) + 1 נוסף = 6 ריבועים → 1 ריבוע עודף.', 6, '{"elo":1380,"discrimination":0.8498968577094996,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_044', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'חץ מצביע ימינה →. מסתכלים עליו במראה אנכית. לאן יצביע?', NULL, '[{"id":"a","text":"ימינה","isCorrect":false},{"id":"b","text":"שמאלה","isCorrect":true},{"id":"c","text":"למעלה","isCorrect":false},{"id":"d","text":"למטה","isCorrect":false}]'::jsonb, 'b', 'מראה אנכית הופכת ימין-שמאל. חץ → (ימינה) יופיע ← (שמאלה) במראה.', 4, '{"elo":1250,"discrimination":0.8053680069566315,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_045', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'קוביה 2×2×2 בנויה מ-8 קוביות קטנות. מצבעים פנים מסוימות. כמה פנים צבועים יש בסך הכל בקוביה שלמה לפני חיתוך?', NULL, '[{"id":"a","text":"6","isCorrect":true},{"id":"b","text":"12","isCorrect":false},{"id":"c","text":"24","isCorrect":false},{"id":"d","text":"48","isCorrect":false}]'::jsonb, 'a', 'קוביה 2×2×2 בחוץ: 6 פנים (כמו כל קוביה). לפני חיתוך לקוביות קטנות — רק 6 פנים חיצוניות.', 7, '{"elo":1440,"discrimination":0.8533020865576072,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_046', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'פירמידה עם בסיס ריבועי 4×4 וגובה 3. אם חותכים אותה בגובה 1.5 (בדיוק באמצע) — מה שטח חתך?', NULL, '[{"id":"a","text":"1×1","isCorrect":false},{"id":"b","text":"2×2","isCorrect":true},{"id":"c","text":"3×3","isCorrect":false},{"id":"d","text":"4×4","isCorrect":false}]'::jsonb, 'b', 'בגובה מחצית, הממד הוא חצי הבסיס. 4÷2=2. חתך = 2×2=4 יח² (ריבוע 2×2).', 5, '{"elo":1315,"discrimination":0.8080609355292883,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_047', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'קוביה 3×3×3 — כמה קוביות 1×1×1 נוגעות לפחות בקצה אחד (אך לא בפנים שלמה) של הקוביה הגדולה?', NULL, '[{"id":"a","text":"8","isCorrect":false},{"id":"b","text":"12","isCorrect":true},{"id":"c","text":"24","isCorrect":false},{"id":"d","text":"36","isCorrect":false}]'::jsonb, 'b', 'קוביות על קצוות (לא פינות): כל קצה יש 1 קובייה פנימית בקצה (3-2=1). 12 קצוות × 1 = 12.', 6, '{"elo":1380,"discrimination":0.8733716780254,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_048', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'עיגול עם רדיוס 7 ס"מ. מה ההיקף? (π≈22/7)', NULL, '[{"id":"a","text":"22 ס\"מ","isCorrect":false},{"id":"b","text":"44 ס\"מ","isCorrect":true},{"id":"c","text":"154 ס\"מ","isCorrect":false},{"id":"d","text":"77 ס\"מ","isCorrect":false}]'::jsonb, 'b', 'היקף = 2πr = 2×(22/7)×7 = 2×22 = 44 ס"מ.', 4, '{"elo":1250,"discrimination":0.841199676900402,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true),
  ('q_spatial_049', 'topic_spatial', '["target_psychometric","target_tayyas","target_ktzina"]'::jsonb, 'shapes', 'צורה עם 8 צלעות שוות. מה שמה?', NULL, '[{"id":"a","text":"משושה","isCorrect":false},{"id":"b","text":"משולש","isCorrect":false},{"id":"c","text":"מתומן","isCorrect":true},{"id":"d","text":"מחומש","isCorrect":false}]'::jsonb, 'c', 'מתומן = אוקטגון = 8 צלעות. משושה=6, מחומש=5, משולש=3.', 3, '{"elo":1150,"discrimination":0.7841245551471824,"guessProbability":0.25}'::jsonb, 'free', 'validated', true, true)
